-- V6 is additive. Inventory and previous research are preserved before classification.
create table private.v6_inventory_backup(id uuid primary key default gen_random_uuid(),table_name text not null,row_id uuid not null,snapshot jsonb not null,created_at timestamptz not null default now());
alter table private.v6_inventory_backup enable row level security;create policy service_only on private.v6_inventory_backup for all to service_role using(true) with check(true);revoke all on private.v6_inventory_backup from public,anon,authenticated;grant all on private.v6_inventory_backup to service_role;
insert into private.v6_inventory_backup(table_name,row_id,snapshot) select 'websites',id,to_jsonb(w) from public.websites w union all select 'publisher_catalog',id,to_jsonb(p) from public.publisher_catalog p;
insert into public.permissions values('websites.read_all','Read all workspace websites'),('websites.assign','Assign website resources') on conflict do nothing;
insert into public.role_permissions select r,p from unnest(array['super_admin','admin','seo_manager']) r cross join unnest(array['websites.read_all','websites.assign']) p on conflict do nothing;
alter table public.websites add column inventory_excluded boolean not null default false,add column inventory_audit_class text not null default 'owner_unverified';
create table public.website_assignments(tenant_id uuid not null,website_id uuid not null,user_id uuid not null,assigned_by uuid not null,can_publish boolean not null default false,can_connect boolean not null default false,created_at timestamptz not null default now(),primary key(website_id,user_id),foreign key(tenant_id,website_id) references public.websites(tenant_id,id),foreign key(tenant_id,user_id) references public.profiles(tenant_id,id),foreign key(tenant_id,assigned_by) references public.profiles(tenant_id,id));
create index website_assignments_user_idx on public.website_assignments(tenant_id,user_id,website_id);create index website_assignments_author_idx on public.website_assignments(tenant_id,assigned_by);
create function private.website_domain(p_url text) returns text language sql immutable set search_path='' as $$ select lower(regexp_replace(split_part(split_part(p_url,'://',2),'/',1),'^www\.','')) $$;
create function private.placeholder_domain(p_domain text) returns boolean language sql immutable set search_path='' as $$ select p_domain ~* '(^|\.)(example\.(com|net|org|edu)|localhost|local|internal|test|invalid|example|onion)$' $$;
update public.websites set inventory_excluded=true,inventory_audit_class='reserved_placeholder' where private.placeholder_domain(private.website_domain(website_url));
create function private.actor_website_access(p_actor uuid,p_website uuid,p_scope text default 'read') returns boolean language sql stable set search_path='' as $$
 select p_scope in ('read','publish','connect') and exists(select 1 from public.profiles p join public.websites w on w.tenant_id=p.tenant_id left join public.website_assignments s on s.website_id=w.id and s.user_id=p.id where p.id=p_actor and p.active and not p.password_change_required and w.id=p_website and (p_scope<>'read' or private.actor_permission(p.id,'websites.read')) and (private.actor_permission(p.id,'websites.read_all') or w.owner_id=p.id or s.user_id is not null and (p_scope='read' or p_scope='publish' and s.can_publish or p_scope='connect' and s.can_connect)))
$$;
revoke all on function private.actor_website_access(uuid,uuid,text) from public,anon,authenticated;grant execute on function private.actor_website_access(uuid,uuid,text) to service_role;
create function private.can_read_website(p_website uuid) returns boolean language sql stable security definer set search_path='' as $$ select private.has_permission('websites.read') and private.actor_website_access((select auth.uid()),p_website,'read') $$;
revoke all on function private.can_read_website(uuid) from public,anon;grant execute on function private.can_read_website(uuid) to authenticated,service_role;
drop policy websites_read on public.websites;create policy websites_read on public.websites for select to authenticated using(tenant_id=(select private.tenant_id()) and private.can_read_website(id));
alter policy tenant_read on public.website_metrics using(tenant_id=(select private.tenant_id()) and private.can_read_website(website_id));
alter table public.tasks add column website_id uuid,add foreign key(tenant_id,website_id) references public.websites(tenant_id,id);create index tasks_website_idx on public.tasks(tenant_id,website_id);
alter table public.articles add column seo_instructions jsonb not null default '{}';
-- Imported row identity includes sheet and physical row; blank rows are documented too.
alter table public.import_batches drop constraint import_batches_total_rows_check;alter table public.import_batches add check(total_rows between 1 and 100000);
create table public.workbook_imports(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,batch_id uuid not null,owner_id uuid not null,filename text not null,source_sha256 text not null check(source_sha256 ~ '^[a-f0-9]{64}$'),storage_path text not null,source_proofs jsonb not null,manifest jsonb not null,total_rows integer not null check(total_rows between 1 and 100000),received_rows integer not null default 0,next_chunk integer not null default 0,status text not null default 'uploading' check(status in ('uploading','verifying','complete')),file_verified_at timestamptz not null default now(),created_at timestamptz not null default now(),sealed_at timestamptz,unique(tenant_id,id),unique(tenant_id,source_sha256),foreign key(tenant_id,batch_id) references public.import_batches(tenant_id,id),foreign key(tenant_id,owner_id) references public.profiles(tenant_id,id));
create index workbook_owner_idx on public.workbook_imports(tenant_id,owner_id);create index workbook_batch_idx on public.workbook_imports(tenant_id,batch_id);
alter table public.import_rows drop constraint import_rows_batch_id_row_number_key;
alter table public.import_rows add column workbook_id uuid,add column source_sheet text not null default 'Legacy',add column sequence_number integer,add column supplied_data jsonb not null default '{}',add column source_details jsonb not null default '{}',add column supplied_metrics jsonb not null default '{}',add unique(tenant_id,id),add unique(batch_id,source_sheet,row_number),add foreign key(tenant_id,workbook_id) references public.workbook_imports(tenant_id,id);
create unique index import_row_sequence_idx on public.import_rows(batch_id,sequence_number) where sequence_number is not null;create index import_row_workbook_idx on public.import_rows(tenant_id,workbook_id,website_id);
create table public.workbook_chunks(workbook_id uuid not null,tenant_id uuid not null,chunk_index integer not null,digest text not null,row_count integer not null check(row_count between 1 and 500),created_at timestamptz not null default now(),primary key(workbook_id,chunk_index),foreign key(tenant_id,workbook_id) references public.workbook_imports(tenant_id,id));create index workbook_chunks_tenant_idx on public.workbook_chunks(tenant_id,workbook_id);
create table public.website_qualifications(website_id uuid primary key,tenant_id uuid not null,reachability_status text not null default 'verification_pending' check(reachability_status in ('verification_pending','reachable','redirected','temporarily_unavailable','access_restricted','broken_inactive')),reachability_evidence jsonb not null default '{}',reachability_checked_at timestamptz,last_successful_at timestamptz,editorial_review text not null default 'pending' check(editorial_review in ('pending','approved','rejected')),reviewed_by uuid,review_notes text not null default '',reviewed_content_sha text,reviewed_at timestamptz,guest_submission_status text not null default 'unverified',guidelines_url text,guidelines_evidence jsonb not null default '{}',updated_at timestamptz not null default now(),created_at timestamptz not null default now(),unique(tenant_id,website_id),foreign key(tenant_id,website_id) references public.websites(tenant_id,id),foreign key(tenant_id,reviewed_by) references public.profiles(tenant_id,id));create index qualifications_reviewer_idx on public.website_qualifications(tenant_id,reviewed_by);
insert into public.website_qualifications(website_id,tenant_id) select id,tenant_id from public.websites;
create table public.qualification_checks(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,website_id uuid not null,target_url text not null,requested_by uuid not null,include_metrics boolean not null default false,status text not null default 'queued' check(status in ('queued','processing','complete','error')),attempts integer not null default 0,lease_token uuid,lease_until timestamptz,next_check_at timestamptz not null default now(),result jsonb,created_at timestamptz not null default now(),completed_at timestamptz,foreign key(tenant_id,website_id) references public.websites(tenant_id,id),foreign key(tenant_id,requested_by) references public.profiles(tenant_id,id));create index qualification_due_idx on public.qualification_checks(next_check_at,created_at) where status in ('queued','processing');create index qualification_site_idx on public.qualification_checks(tenant_id,website_id);create index qualification_actor_idx on public.qualification_checks(tenant_id,requested_by);create unique index qualification_active_idx on public.qualification_checks(website_id) where status in ('queued','processing');
alter table public.publisher_catalog add column catalog_scope text not null default 'legacy_research';
alter table public.settings add column qualification_policy jsonb not null default '{"minimum_da":30,"maximum_spam":5,"minimum_traffic":1000,"traffic_required":true}';
update public.settings set quality_filters=quality_filters||'{"minimum_da":30,"maximum_spam":5,"enabled":true}',publisher_filters=publisher_filters||'{"minimum_da":30,"maximum_spam":5}';
do $$ declare t text;begin foreach t in array array['website_assignments','workbook_imports','workbook_chunks','website_qualifications','qualification_checks'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
create policy assignments_read on public.website_assignments for select to authenticated using(tenant_id=(select private.tenant_id()) and (user_id=(select auth.uid()) or private.has_permission('websites.assign')));
create policy workbook_read on public.workbook_imports for select to authenticated using(tenant_id=(select private.tenant_id()) and private.has_permission('websites.create') and (owner_id=(select auth.uid()) or private.has_permission('websites.read_all')));
create policy chunks_read on public.workbook_chunks for select to authenticated using(exists(select 1 from public.workbook_imports w where w.id=workbook_id and w.tenant_id=workbook_chunks.tenant_id));
create policy qualification_read on public.website_qualifications for select to authenticated using(tenant_id=(select private.tenant_id()) and private.can_read_website(website_id));
create policy qualification_checks_read on public.qualification_checks for select to authenticated using(tenant_id=(select private.tenant_id()) and private.can_read_website(website_id));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('workbook-sources','workbook-sources',false,20971520,array['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.ms-excel','text/csv','application/octet-stream']) on conflict(id) do nothing;
create policy workbook_source_insert on storage.objects for insert to authenticated with check(bucket_id='workbook-sources' and private.has_permission('websites.create') and (storage.foldername(name))[1]=(select private.tenant_id())::text and (storage.foldername(name))[2]=(select auth.uid())::text);
create policy workbook_source_read on storage.objects for select to authenticated using(bucket_id='workbook-sources' and private.has_permission('websites.create') and (storage.foldername(name))[1]=(select private.tenant_id())::text and ((storage.foldername(name))[2]=(select auth.uid())::text or private.has_permission('websites.read_all')));

create function public.start_workbook_import(p_actor uuid,p_filename text,p_sha text,p_storage_path text,p_manifest jsonb,p_source_proofs jsonb) returns jsonb language plpgsql set search_path='' as $$ declare a public.profiles;w public.workbook_imports;b uuid;n integer;begin
 select * into a from public.profiles where id=p_actor and active;if not private.actor_permission(p_actor,'websites.create') then raise exception 'Import permission required';end if;
 if jsonb_typeof(p_manifest)<>'array' or jsonb_array_length(p_manifest) not between 1 and 200 or p_sha !~ '^[a-f0-9]{64}$' then raise exception 'A full validated workbook manifest is required';end if;
 select sum((s->>'row_count')::integer) into n from jsonb_array_elements(p_manifest) s;if n not between 1 and 100000 or exists(select 1 from jsonb_array_elements(p_manifest) s where length(s->>'name') not between 1 and 100 or (s->>'header_row')::integer<1 or (s->>'row_count')::integer<1) or (select count(distinct s->>'name') from jsonb_array_elements(p_manifest) s)<>jsonb_array_length(p_manifest) then raise exception 'Invalid sheet ranges';end if;
 if jsonb_typeof(p_source_proofs)<>'array' or jsonb_array_length(p_source_proofs)<>ceil(n/500.0) then raise exception 'Server-verified source chunk proofs required';end if;perform 1 from public.tenants where id=a.tenant_id for update;select * into w from public.workbook_imports where tenant_id=a.tenant_id and source_sha256=p_sha;
 if w.id is not null then if w.owner_id<>a.id and not private.actor_permission(a.id,'websites.read_all') then raise exception 'This workbook is managed by another workspace employee';end if;if w.manifest<>p_manifest or w.total_rows<>n or w.source_proofs<>p_source_proofs then raise exception 'This source hash has a different import manifest';end if;return to_jsonb(w);end if;
 insert into public.import_batches(tenant_id,owner_id,request_id,filename,total_rows) values(a.tenant_id,a.id,gen_random_uuid(),left(p_filename,200),n) returning id into b;
 insert into public.workbook_imports(tenant_id,batch_id,owner_id,filename,source_sha256,storage_path,source_proofs,manifest,total_rows) values(a.tenant_id,b,a.id,left(p_filename,200),p_sha,p_storage_path,p_source_proofs,p_manifest,n) returning * into w;return to_jsonb(w);
end $$;
create function public.import_workbook_chunk(p_actor uuid,p_workbook uuid,p_index integer,p_rows jsonb,p_source_digest text) returns jsonb language plpgsql set search_path='' as $$ declare a public.profiles;w public.workbook_imports;r jsonb;sheet jsonb;wid uuid;st text;digest text;prior public.workbook_chunks;i integer:=0;count_rows integer;added integer:=0;duplicates integer:=0;invalid integer:=0;begin
 select * into a from public.profiles where id=p_actor and active;if not private.actor_permission(p_actor,'websites.create') then raise exception 'Import permission required';end if;
 select * into w from public.workbook_imports where id=p_workbook and tenant_id=a.tenant_id and (owner_id=a.id or private.actor_permission(a.id,'websites.read_all')) for update;if w.id is null then raise exception 'Workbook not found';end if;
 if p_source_digest is distinct from w.source_proofs->>p_index then raise exception 'Chunk differs from the saved original workbook';end if;if jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows) not between 1 and 500 then raise exception 'Send 1–500 rows per resumable chunk';end if;count_rows:=jsonb_array_length(p_rows);digest:=encode(extensions.digest(p_rows::text,'sha256'),'hex');select * into prior from public.workbook_chunks where workbook_id=w.id and chunk_index=p_index;
 if prior.workbook_id is not null then if prior.digest<>digest then raise exception 'A committed chunk cannot be replaced';end if;return jsonb_build_object('replayed',true,'received_rows',w.received_rows,'next_chunk',w.next_chunk);end if;
 if w.status<>'uploading' or p_index<>w.next_chunk or w.received_rows+count_rows>w.total_rows or (w.received_rows+count_rows<w.total_rows and count_rows<>500) then raise exception 'Resume from the next complete chunk';end if;
 perform 1 from public.tenants where id=a.tenant_id for update;
 for r in select value from jsonb_array_elements(p_rows) loop
  i:=i+1;wid:=null;select s into sheet from jsonb_array_elements(w.manifest) s where s->>'name'=r->>'source_sheet';if sheet is null or (r->>'row_number')::integer not between (sheet->>'header_row')::integer+1 and (sheet->>'header_row')::integer+(sheet->>'row_count')::integer or (r->>'sequence_number')::integer<>w.received_rows+i then raise exception 'Source sheet/row sequence does not match the workbook';end if;
  st:=r->>'status';if st='pending' then
   if private.placeholder_domain(r->>'domain') then raise exception 'Reserved example domains cannot enter inventory';end if;
   select id into wid from public.websites where tenant_id=a.tenant_id and private.website_domain(website_url)=r->>'domain' order by created_at,id limit 1;
   if wid is not null then st:='duplicate';duplicates:=duplicates+1;else insert into public.websites(tenant_id,owner_id,website_name,website_url,api_endpoint,cms_type,category,language,country,account_email,inventory_audit_class) values(a.tenant_id,a.id,r->>'website_name',r->>'website_url',r->>'website_url','custom',coalesce(r->>'category',''),coalesce(nullif(r->>'language',''),'en'),coalesce(r->>'country',''),coalesce(r->>'account_email',''),'spreadsheet_pending') returning id into wid;added:=added+1;end if;
   insert into public.website_qualifications(website_id,tenant_id) values(wid,a.tenant_id) on conflict do nothing;
  else st:='invalid';invalid:=invalid+1;end if;
  insert into public.import_rows(tenant_id,batch_id,workbook_id,row_number,source_sheet,sequence_number,website_id,website_url,status,cms_hint,supplied_data,source_details,supplied_metrics,error_code,message,completed_at) values(a.tenant_id,w.batch_id,w.id,(r->>'row_number')::integer,r->>'source_sheet',(r->>'sequence_number')::integer,wid,coalesce(r->>'website_url',''),st,coalesce(r->>'cms_hint',''),coalesce(r->'supplied_data','{}'),coalesce(r->'source_details','{}'),coalesce(r->'supplied_metrics','{}'),case when st='duplicate' then 'duplicate_domain' else r->>'error_code' end,case when st='duplicate' then 'Existing domain retained; source row linked without overwriting its connection.' when st='pending' then 'Source recorded; qualification begins after the complete workbook is sealed.' else r->>'message' end,case when st in ('invalid','duplicate') then clock_timestamp() end);
 end loop;
 insert into public.workbook_chunks values(w.id,a.tenant_id,p_index,digest,count_rows,clock_timestamp());update public.workbook_imports set received_rows=received_rows+count_rows,next_chunk=next_chunk+1 where id=w.id returning * into w;return jsonb_build_object('id',w.id,'received_rows',w.received_rows,'next_chunk',w.next_chunk,'added',added,'duplicates',duplicates,'invalid',invalid);
end $$;
create function public.seal_workbook_import(p_actor uuid,p_workbook uuid,p_metrics boolean default false) returns jsonb language plpgsql set search_path='' as $$ declare a public.profiles;w public.workbook_imports;begin
 select * into a from public.profiles where id=p_actor and active;if not private.actor_permission(p_actor,'websites.create') then raise exception 'Import permission required';end if;select * into w from public.workbook_imports where id=p_workbook and tenant_id=a.tenant_id and (owner_id=a.id or private.actor_permission(a.id,'websites.read_all')) for update;
 if w.id is null or w.received_rows<>w.total_rows or (select count(*) from public.import_rows where workbook_id=w.id)<>w.total_rows then raise exception 'Every workbook row must be recorded before qualification';end if;
 if w.status in ('uploading','complete','verifying') then update public.workbook_imports set status='verifying',sealed_at=clock_timestamp() where id=w.id;insert into public.qualification_checks(tenant_id,website_id,target_url,requested_by,include_metrics) select distinct r.tenant_id,r.website_id,s.website_url,a.id,p_metrics from public.import_rows r join public.websites s on s.id=r.website_id where r.workbook_id=w.id and r.website_id is not null and not s.inventory_excluded on conflict do nothing;update public.import_rows set status='discovered',message='Source recorded. Reachability, licensed SEO metrics and permission verification are separate.',completed_at=clock_timestamp() where workbook_id=w.id and status='pending';end if;
 update public.workbook_imports set status='complete' where id=w.id and not exists(select 1 from public.import_rows s join public.qualification_checks c on c.website_id=s.website_id and c.status in ('queued','processing') where s.workbook_id=w.id);return jsonb_build_object('id',w.id,'rows_recorded',w.total_rows,'message','Full workbook recorded. Background qualification continues after this page closes.');
end $$;

create function private.fresh_website_metric(p_website uuid,p_metric text,p_provider text default null) returns numeric language sql stable set search_path='' as $$ select value from public.website_metrics where website_id=p_website and metric=p_metric and verification='provider_verified' and value>=0 and value<>'NaN'::numeric and (p_metric not in ('domain_authority','spam_score') or value<=100) and (p_provider is null or provider=p_provider) and observed_at>now()-interval '30 days' and observed_at<=now()+interval '5 minutes' $$;
create function private.website_state(p_website uuid) returns jsonb language plpgsql stable set search_path='' as $$
declare w public.websites;q public.website_qualifications;policy jsonb;source_found boolean;da numeric;spam numeric;traffic numeric;quality text;reason text;group_name text;publication text;reach_ok boolean;quality_ok boolean;connection_ok boolean;worker_ok boolean;ready boolean;label_mismatch boolean;begin
 select * into w from public.websites where id=p_website;if w.id is null then return null;end if;select * into q from public.website_qualifications where website_id=w.id;select qualification_policy into policy from public.settings where tenant_id=w.tenant_id;
 source_found:=exists(select 1 from public.import_rows r join public.workbook_imports b on b.id=r.workbook_id and b.tenant_id=r.tenant_id where r.website_id=w.id and r.tenant_id=w.tenant_id and r.status in ('pending','duplicate','discovered') and b.status in ('verifying','complete') and b.received_rows=b.total_rows and b.file_verified_at is not null and private.website_domain(r.website_url)=private.website_domain(w.website_url));
 da:=private.fresh_website_metric(w.id,'domain_authority','moz');spam:=private.fresh_website_metric(w.id,'spam_score','moz');traffic:=private.fresh_website_metric(w.id,'estimated_organic_traffic');
 quality:=case when da<greatest(30,coalesce((policy->>'minimum_da')::numeric,30)) and spam>=least(5,coalesce((policy->>'maximum_spam')::numeric,5)) then 'rejected_both_metrics' when da<greatest(30,coalesce((policy->>'minimum_da')::numeric,30)) then 'rejected_low_da' when spam>=least(5,coalesce((policy->>'maximum_spam')::numeric,5)) then 'rejected_high_spam' when da is null or spam is null then 'pending_seo_verification' when coalesce((policy->>'traffic_required')::boolean,true) and (traffic is null or traffic<coalesce((policy->>'minimum_traffic')::numeric,1000)) then 'manual_review_required' else 'metrics_verified' end;
 label_mismatch:=w.website_name ~* '^[a-z0-9.-]+\.[a-z]{2,}$' and lower(regexp_replace(w.website_name,'^www\.',''))<>private.website_domain(w.website_url);
 reach_ok:=coalesce(q.reachability_status='reachable' and q.reachability_checked_at>now()-interval '7 days',false);
 quality_ok:=quality='metrics_verified' and coalesce(q.editorial_review='approved' and q.reviewed_content_sha=q.reachability_evidence->>'content_sha' and q.reviewed_at>now()-interval '30 days',false) and not label_mismatch;
 worker_ok:=w.connection_method<>'browser' or exists(select 1 from public.browser_workers b where b.tenant_id=w.tenant_id and b.active and b.last_seen_at>now()-interval '2 minutes');
 connection_ok:=w.status='active' and w.connection_status='connected' and w.permission_status='verified' and w.cms_type<>'manual' and w.tested_at>now()-interval '7 days' and worker_ok and exists(select 1 from private.website_credentials c where c.website_id=w.id);
 ready:=source_found and reach_ok and quality_ok and coalesce(connection_ok,false) and not w.inventory_excluded and not private.placeholder_domain(private.website_domain(w.website_url));
 reason:=case when w.inventory_excluded or private.placeholder_domain(private.website_domain(w.website_url)) then 'This record is quarantined or uses a reserved example domain.' when not source_found then 'The original owner spreadsheet must identify this domain before it can enter the qualified network.' when q.reachability_status='broken_inactive' then 'The reachability check found an inactive or parked website; review the recorded evidence.' when not reach_ok then 'A successful, current reachability check of the supplied domain is required. Redirects, restrictions and temporary failures require review.' when quality='rejected_both_metrics' then 'Verified Moz DA is too low and Spam Score is too high.' when quality='rejected_low_da' then 'Verified Moz DA is below the required minimum of at least 30.' when quality='rejected_high_spam' then 'Verified Moz Spam Score must be strictly below 5% (or a stricter saved limit).' when quality='pending_seo_verification' then 'Current licensed Moz DA and Spam Score are missing. Supplied spreadsheet values do not qualify.' when quality='manual_review_required' then 'Required traffic evidence is missing or below the configured minimum.' when label_mismatch then 'The saved website name and actual domain disagree. Review the original record.' when q.editorial_review='rejected' then 'Editorial quality review rejected this website.' when not quality_ok then 'Review the current page for editorial quality, relevance and publication history.' when not worker_ok then 'The required production browser worker is offline or unregistered.' when not coalesce(connection_ok,false) then 'The connector needs current, verified publishing authorization.' else 'Spreadsheet provenance, current SEO/reachability evidence, editorial quality and publishing authorization are verified.' end;
 group_name:=case when w.inventory_excluded or private.placeholder_domain(private.website_domain(w.website_url)) or q.reachability_status='broken_inactive' or quality like 'rejected_%' or q.editorial_review='rejected' then 'rejected' when ready then 'qualified_network' when source_found and reach_ok and quality_ok and q.guest_submission_status='verified_guidelines' then 'qualified_prospect' else 'pending_verification' end;
 publication:=case when ready then 'auto_publishing_ready' when group_name='rejected' and quality like 'rejected_%' then 'rejected_seo_criteria' when not reach_ok then case when q.reachability_status is null or q.reachability_status='verification_pending' then 'verification_pending' when q.reachability_status='reachable' then 'verification_expired' else q.reachability_status end when q.guest_submission_status='verified_guidelines' and not coalesce(connection_ok,false) then 'publisher_submission_available' when w.permission_status<>'verified' and w.connection_status='connected' then 'publishing_permission_pending' when w.connection_status in ('authorization_required','revoked','untested') then 'authorization_required' when w.connection_status in ('unsupported','manual') then 'unsupported_automation' else 'connector_configuration_required' end;
 return jsonb_build_object('auto_ready',ready,'group',group_name,'quality_status',quality,'publishing_status',publication,'reason',reason,'spreadsheet_source',source_found,'domain_authority',da,'spam_score',spam,'organic_traffic',traffic,'reachability_status',coalesce(q.reachability_status,'verification_pending'),'reachability_checked_at',q.reachability_checked_at,'reachability_evidence',q.reachability_evidence,'last_successful_at',q.last_successful_at,'editorial_review',coalesce(q.editorial_review,'pending'),'review_notes',q.review_notes,'reviewed_at',q.reviewed_at,'label_mismatch',label_mismatch,'guest_submission_status',coalesce(q.guest_submission_status,'unverified'),'guidelines_url',q.guidelines_url,'guidelines_evidence',q.guidelines_evidence,'worker_online',worker_ok,'connection_verified',coalesce(connection_ok,false));
end $$;
create function private.website_is_ready(p_website uuid) returns boolean language sql stable set search_path='' as $$ select coalesce((private.website_state(p_website)->>'auto_ready')::boolean,false) $$;
create function public.website_access(p_actor uuid,p_website uuid,p_scope text default 'read') returns boolean language sql stable set search_path='' as $$ select private.actor_website_access(p_actor,p_website,p_scope) $$;
create function public.inventory_readiness(p_actor uuid,p_offset integer default 0,p_limit integer default 500) returns jsonb language sql stable set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'qualification',private.website_state(s.id),'can_publish',private.actor_website_access(p_actor,s.id,'publish'),'can_connect',private.actor_website_access(p_actor,s.id,'connect'))),'[]') from (select w.id from public.websites w where private.actor_website_access(p_actor,w.id,'read') and private.actor_permission(p_actor,'websites.read') order by w.created_at,w.id offset greatest(0,p_offset) limit greatest(1,least(500,p_limit))) s
$$;
create function public.enqueue_qualification(p_actor uuid,p_sites uuid[],p_metrics boolean default false) returns integer language plpgsql set search_path='' as $$ declare a public.profiles;n integer;begin
 select * into a from public.profiles where id=p_actor and active;if a.id is null or not (private.actor_permission(a.id,'publishers.research') or private.actor_permission(a.id,'websites.connect')) then raise exception 'Verification permission required';end if;if cardinality(p_sites) not between 1 and 500 then raise exception 'Queue 1–500 website checks per request';end if;
 if exists(select 1 from unnest(p_sites) s where not private.actor_website_access(a.id,s,'read')) then raise exception 'A website is not assigned to this account';end if;
 insert into public.qualification_checks(tenant_id,website_id,target_url,requested_by,include_metrics) select w.tenant_id,w.id,w.website_url,a.id,p_metrics from public.websites w where w.id=any(p_sites) and w.tenant_id=a.tenant_id and not w.inventory_excluded on conflict do nothing;get diagnostics n=row_count;return n;
end $$;
create function public.claim_qualification_check() returns jsonb language plpgsql set search_path='' as $$ declare r public.qualification_checks;w public.websites;begin
 perform pg_advisory_xact_lock(hashtextextended('v6-qualification-claims',0));update public.qualification_checks set status='error',completed_at=now(),result='{"error":"requester_access_revoked"}' where status='queued' and not private.actor_website_access(requested_by,website_id,'read');
 update public.qualification_checks set status=case when attempts<3 then 'queued' else 'error' end,lease_token=null,lease_until=null,next_check_at=now()+interval '1 minute' where status='processing' and lease_until<now();
 if (select count(*) from public.qualification_checks where status='processing')>=3 then return null;end if;
 select * into r from public.qualification_checks where status='queued' and next_check_at<=now() and attempts<3 and private.actor_website_access(requested_by,website_id,'read') and (private.actor_permission(requested_by,'publishers.research') or private.actor_permission(requested_by,'websites.connect')) order by created_at for update skip locked limit 1;if r.id is null then return null;end if;
 select * into w from public.websites where id=r.website_id and tenant_id=r.tenant_id;
 update public.qualification_checks set status='processing',attempts=attempts+1,lease_token=gen_random_uuid(),lease_until=now()+interval '3 minutes' where id=r.id returning * into r;
 return jsonb_build_object('can_test_connection',private.actor_permission(r.requested_by,'websites.connect') and private.actor_website_access(r.requested_by,w.id,'connect'),'check',to_jsonb(r),'website',to_jsonb(w),'source',(select to_jsonb(s) from public.import_rows s join public.workbook_imports b on b.id=s.workbook_id where s.website_id=w.id and b.status in ('verifying','complete') order by b.created_at desc,s.row_number limit 1));
end $$;
create function public.finish_qualification_check(p_check uuid,p_token uuid,p_result jsonb) returns void language plpgsql set search_path='' as $$ declare r public.qualification_checks;w public.websites;reach text;begin
 select * into r from public.qualification_checks where id=p_check and lease_token=p_token and lease_until>now() and status='processing' for update;if r.id is null then raise exception 'Qualification check lease expired';end if;select * into w from public.websites where id=r.website_id;
 if w.website_url<>r.target_url then update public.qualification_checks set status='error',result='{"error":"website_changed"}',completed_at=clock_timestamp(),lease_token=null,lease_until=null where id=r.id;return;end if;
 reach:=p_result->'reachability'->>'status';if reach not in ('verification_pending','reachable','redirected','temporarily_unavailable','access_restricted','broken_inactive') then raise exception 'Unsupported reachability classification';end if;
 insert into public.website_qualifications(website_id,tenant_id,reachability_status,reachability_evidence,reachability_checked_at,last_successful_at,guest_submission_status,guidelines_url,guidelines_evidence) values(w.id,w.tenant_id,reach,p_result->'reachability',clock_timestamp(),case when reach in ('reachable','redirected') then clock_timestamp() end,coalesce(p_result->'guidelines'->>'status','unverified'),p_result->'guidelines'->>'url',coalesce(p_result->'guidelines','{}')) on conflict(website_id) do update set reachability_status=excluded.reachability_status,reachability_evidence=excluded.reachability_evidence,reachability_checked_at=excluded.reachability_checked_at,last_successful_at=coalesce(excluded.last_successful_at,public.website_qualifications.last_successful_at),guest_submission_status=excluded.guest_submission_status,guidelines_url=excluded.guidelines_url,guidelines_evidence=excluded.guidelines_evidence,updated_at=clock_timestamp();
 update public.websites set cms_type=case when connection_status in ('untested','setup_required','error','authorization_required') and p_result->'discovery'->>'platform' in ('wordpress','blogger','ghost','shopify','webflow','wix','drupal','joomla','custom') and not exists(select 1 from private.website_credentials c where c.website_id=w.id) then p_result->'discovery'->>'platform' else cms_type end where id=w.id;
 if p_result->'auth_test' is not null and p_result->'auth_test'<>'null'::jsonb and (p_result->'auth_test'->>'connection_version')::integer=w.connection_version then update public.websites set connection_status=case when (p_result->'auth_test'->>'success')::boolean then 'connected' else 'error' end,permission_status=case when (p_result->'auth_test'->>'success')::boolean then coalesce(p_result->'auth_test'->>'permission_status','unverified') else 'unverified' end,tested_at=clock_timestamp(),connection_message=left(p_result->'auth_test'->>'message',1000) where id=w.id and connection_version=w.connection_version;end if;
 update public.qualification_checks set status='complete',result=p_result,completed_at=clock_timestamp(),lease_token=null,lease_until=null where id=r.id;
 update public.workbook_imports b set status='complete' where status='verifying' and exists(select 1 from public.import_rows s where s.workbook_id=b.id and s.website_id=w.id) and not exists(select 1 from public.import_rows s join public.qualification_checks c on c.website_id=s.website_id and c.status in ('queued','processing') where s.workbook_id=b.id);
end $$;
-- Changes to the URL invalidate observations/review; existing credentials retain their own binding fence.
create function private.invalidate_website_review() returns trigger language plpgsql set search_path='' as $$ begin if new.website_url is distinct from old.website_url then update public.website_qualifications set reachability_status='verification_pending',reachability_checked_at=null,editorial_review='pending',reviewed_at=null,updated_at=clock_timestamp() where website_id=new.id;end if;return new;end $$;
create trigger invalidate_website_review after update of website_url on public.websites for each row execute function private.invalidate_website_review();
alter function public.create_campaign(uuid,uuid,text,uuid[],integer,timestamptz,jsonb) rename to create_campaign_v5;
create function public.create_campaign(p_actor uuid,p_article uuid,p_name text,p_sites uuid[],p_interval integer,p_start timestamptz,p_overrides jsonb default '{}') returns uuid language plpgsql set search_path='' as $$ begin
 if not private.actor_permission(p_actor,'campaigns.launch') or exists(select 1 from unnest(p_sites) s where not private.actor_website_access(p_actor,s,'publish') or not private.website_is_ready(s)) then raise exception 'Every target must come from the owner spreadsheet and pass current Moz DA>=30, Spam Score<5, quality, reachability, assignment and publishing-permission checks';end if;
 if not exists(select 1 from public.articles a where a.id=p_article and (private.actor_permission(p_actor,'articles.read_all') or a.owner_id=p_actor or a.assigned_to=p_actor)) then raise exception 'Article is not assigned to this account';end if;
 return public.create_campaign_v5(p_actor,p_article,p_name,p_sites,p_interval,p_start,p_overrides);end $$;
alter function public.eligible_websites(uuid,text,text,text,text) rename to eligible_websites_v5;
create function public.eligible_websites(p_actor uuid,p_content text,p_category text default '',p_language text default '',p_platform text default '') returns setof public.websites language sql stable set search_path='' as $$ select w.* from public.eligible_websites_v5(p_actor,p_content,p_category,p_language,p_platform) w where private.website_is_ready(w.id) and private.actor_website_access(p_actor,w.id,'publish') $$;
do $$ declare d text;needle text:='and private.actor_permission(c0.owner_id,''campaigns.launch'') and w.status=''active'' and w.connection_status=''connected''';begin d:=pg_get_functiondef('public.claim_next_job(text,uuid)'::regprocedure);if position(needle in d)=0 then raise exception 'Inspect queue before changing the V6 gate';end if;execute replace(d,needle,'and private.actor_permission(c0.owner_id,''campaigns.launch'') and private.actor_website_access(c0.owner_id,w.id,''publish'') and private.website_is_ready(w.id) and w.status=''active'' and w.connection_status=''connected''');end $$;
create or replace function private.can_read_article(p_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.articles a where a.id=p_id and a.archived_at is null and a.tenant_id=(select private.tenant_id()) and (private.has_permission('articles.read') or private.has_permission('campaigns.create')) and (a.owner_id=(select auth.uid()) or a.assigned_to=(select auth.uid()) or private.has_permission('articles.read_all'))) $$;
do $$ declare f record;begin for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('start_workbook_import','import_workbook_chunk','seal_workbook_import','website_access','inventory_readiness','enqueue_qualification','claim_qualification_check','finish_qualification_check','create_campaign','create_campaign_v5','eligible_websites','eligible_websites_v5') loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;end $$;
revoke all on function private.website_state(uuid),private.website_is_ready(uuid),private.fresh_website_metric(uuid,text,text),private.website_domain(text),private.placeholder_domain(text),private.invalidate_website_review() from public,anon,authenticated;
grant execute on function private.website_state(uuid),private.website_is_ready(uuid),private.fresh_website_metric(uuid,text,text),private.website_domain(text),private.placeholder_domain(text) to service_role;

create table private.website_metric_usage(tenant_id uuid not null references public.tenants(id),day date not null,requests integer not null,primary key(tenant_id,day));alter table private.website_metric_usage enable row level security;create policy service_only on private.website_metric_usage for all to service_role using(true) with check(true);revoke all on private.website_metric_usage from public,anon,authenticated;grant all on private.website_metric_usage to service_role;
create function public.consume_website_metric_quota(p_tenant uuid,p_cost integer) returns boolean language plpgsql set search_path='' as $$ declare n integer;maximum integer;begin
 select greatest(1,least(10000,coalesce((qualification_policy->>'metric_daily_limit')::integer,1000))) into maximum from public.settings where tenant_id=p_tenant;
 if maximum is null or p_cost not between 1 and 3 then return false;end if;
 insert into private.website_metric_usage(tenant_id,day,requests) values(p_tenant,current_date,p_cost) on conflict(tenant_id,day) do update set requests=private.website_metric_usage.requests+excluded.requests returning requests into n;return n<=maximum;
end $$;
create function public.assign_website_access(p_actor uuid,p_website uuid,p_employee uuid,p_publish boolean,p_connect boolean,p_remove boolean default false) returns void language plpgsql set search_path='' as $$ declare a public.profiles;begin
 select * into a from public.profiles where id=p_actor and active;if not private.actor_permission(a.id,'websites.assign') or not private.actor_website_access(a.id,p_website,'read') then raise exception 'Website assignment permission required';end if;
 if not exists(select 1 from public.profiles where id=p_employee and tenant_id=a.tenant_id and (p_remove or active)) then raise exception 'Choose an active workspace employee';end if;
 if not p_remove and ((p_publish and (not private.actor_website_access(a.id,p_website,'publish') or not private.actor_permission(a.id,'campaigns.launch'))) or (p_connect and (not private.actor_website_access(a.id,p_website,'connect') or not private.actor_permission(a.id,'websites.connect')))) then raise exception 'You cannot delegate a website permission you do not hold';end if;
 if p_remove then delete from public.website_assignments where website_id=p_website and user_id=p_employee and tenant_id=a.tenant_id;else insert into public.website_assignments(tenant_id,website_id,user_id,assigned_by,can_publish,can_connect) values(a.tenant_id,p_website,p_employee,a.id,p_publish,p_connect) on conflict(website_id,user_id) do update set assigned_by=a.id,can_publish=excluded.can_publish,can_connect=excluded.can_connect;end if;
 insert into public.publishing_logs(tenant_id,actor_id,event_type,message) values(a.tenant_id,a.id,case when p_remove then 'website_access_removed' else 'website_access_assigned' end,'Website resource access updated; global role permissions still apply.');
end $$;
revoke all on function public.assign_website_access(uuid,uuid,uuid,boolean,boolean,boolean),public.consume_website_metric_quota(uuid,integer) from public,anon,authenticated;grant execute on function public.assign_website_access(uuid,uuid,uuid,boolean,boolean,boolean),public.consume_website_metric_quota(uuid,integer) to service_role;

create function public.inventory_website(p_actor uuid,p_website uuid) returns jsonb language sql stable set search_path='' as $$ select private.website_state(p_website) where private.actor_website_access(p_actor,p_website,'read') $$;
create function public.website_publication_ready(p_actor uuid,p_website uuid) returns boolean language sql stable set search_path='' as $$ select private.actor_permission(p_actor,'campaigns.launch') and private.actor_website_access(p_actor,p_website,'publish') and private.website_is_ready(p_website) $$;
revoke all on function public.inventory_website(uuid,uuid),public.website_publication_ready(uuid,uuid) from public,anon,authenticated;
grant execute on function public.inventory_website(uuid,uuid),public.website_publication_ready(uuid,uuid) to service_role;
alter policy tenant_read on public.import_batches using(tenant_id=(select private.tenant_id()) and private.has_permission('websites.create') and (owner_id=(select auth.uid()) or private.has_permission('websites.read_all')));
alter policy tenant_read on public.import_rows using(exists(select 1 from public.import_batches b where b.id=batch_id and b.tenant_id=import_rows.tenant_id));
create function private.tick_qualification() returns void language plpgsql set search_path='' as $$ begin
 perform net.http_post(url:=(select project_url from private.runtime_config where singleton)||'/functions/v1/qualification-worker',headers:=jsonb_build_object('Content-Type','application/json','x-scheduler-token',(select decrypted_secret from vault.decrypted_secrets where name='scheduler_token')),body:='{}'::jsonb,timeout_milliseconds:=120000);
end $$;
revoke all on function private.tick_qualification() from public,anon,authenticated,service_role;
